from fractions import Fraction

def solve(m, n, max_elements=500):
    s = {Fraction(m, n), Fraction(n, m)}
    elements = [Fraction(m, n), Fraction(n, m)]

    # To avoid infinite loop, we use a BFS with a limit
    idx = 0
    while idx < len(elements):
        if 1 in s:
            return True
        if len(elements) > max_elements:
            break

        x = elements[idx]
        for i in range(idx):
            y = elements[i]

            # Try arithmetic mean
            for val in [ (x + y) / 2, (2 * x * y) / (x + y) ]:
                if val not in s:
                    s.add(val)
                    elements.append(val)
                    if val == 1:
                        return True
                    if len(elements) > max_elements:
                        break
            if len(elements) > max_elements:
                break
        idx += 1
    return False

for m in range(1, 10):
    for n in range(m + 1, 20):
        if m == 0: continue # Should not happen
        import math
        if math.gcd(m, n) == 1:
            if solve(m, n):
                print(f"m={m}, n={n}, m+n={m+n}, works=True")
            else:
                print(f"m={m}, n={n}, m+n={m+n}, works=False")

